body.script:

(async function initPortal() {
  const CDN_BASE = "https://cdn.jsdelivr.net/gh/hyperfrog7/Astral@main";
  try {
    const [cssText, htmlText] = await Promise.all([
      fetch(`${CDN_BASE}/style.css?t=${Date.now()}`).then(res => res.text()),
      fetch(`${CDN_BASE}/index.html?t=${Date.now()}`).then(res => res.text())
    ]);

    const styleTag = document.createElement('style');
    styleTag.textContent = cssText;
    document.head.appendChild(styleTag);

    const root = document.getElementById('app-root');
    root.innerHTML = htmlText;

    const scriptTag = document.createElement('script');
    scriptTag.src = `${CDN_BASE}/script.js?t=${Date.now()}`;
    document.body.appendChild(scriptTag);

  } catch (err) {
    console.error('Failed to boot portal from CDN:', err);
  }
})();
